    )
    assert.strictEqual(
      md.render('![alt `code` x`'),
      '<p>![alt <code>code</code> x`</p>\n'
    )
    assert.strictEqual(
      md.render('[`a`b`'),
      '<p>[<code>a</code>b`</p>\n'
    )
    assert.strictEqual(
      zero.render('[foo `bar` baz`'),
      '<p>[foo <code>bar</code> baz`</p>\n'
    )
    assert.strictEqual(
      zero.render('![alt `code` x`'),
      '<p>![alt <code>code</code> x`</p>\n'
