    assert.strictEqual(md.render('![a \\* *b* &amp; c](/u)'),
      '<p><img src="/u" alt="a * b &amp; c"></p>\n')
  })

  it('Should escape surrogate pairs (coverage)', function () {
    const md = markdownit()

    assert.strictEqual(md.render('\\\uD835\uDC9C'), '<p>\\\uD835\uDC9C</p>\n')
